local CS=game:GetService('CollectionService')
local FS=require(game.ServerScriptService.Services.FireService)
local parts=CS:GetTagged('Flammable')
local ok,fail=0,0
local sample={}
local failed={}
for i=1,#parts,40 do local p=parts[i] local r=FS:Ignite(p,nil) if r then ok+=1 if #sample<3 then table.insert(sample,p:GetFullName()) end else fail+=1 if #failed<3 then table.insert(failed,p:GetFullName()) end end end
local burning=#CS:GetTagged('Burning')
return game:GetService('HttpService'):JSONEncode({ok=ok,fail=fail,burning=burning,sample=sample,failed=failed,cnt=FS:CountBurning()})

local CS=game:GetService("CollectionService")
local out={}
out.dropoffs={}
for _,d in CS:GetTagged("RescueDropoff") do table.insert(out.dropoffs,{d:GetFullName(),tostring(d.Position),tostring(d.Size),d.CanTouch,d.CanQuery}) end
out.rescuables={}
local f=workspace:FindFirstChild("Rescuables")
if f then for _,m in f:GetChildren() do table.insert(out.rescuables,{m.Name,m:GetAttribute("RescueState"),m:GetAttribute("Kind")}) end end
out.trucks={}
for _,t in CS:GetTagged("Truck") do table.insert(out.trucks,t:GetFullName()) end
out.spawns=#CS:GetTagged("RescueSpawn")
return game:GetService("HttpService"):JSONEncode(out)

local s=game:GetService("ServerScriptService").Services.RescueService
local ok,src=pcall(function() return s.Source end)
if not ok or not src then return "nosrc "..tostring(src) end
local out={}
for line in string.gmatch(src,"[^\n]+") do if string.find(line,"Dropoff") or string.find(line,"GetPartBounds") or string.find(line,"GetPartsIn") or string.find(line,"Touched") then table.insert(out,line) end end
return table.concat(out,"\n")

local src=game:GetService("ServerScriptService").Services.RescueService.Source
local lines={}
for l in string.gmatch(src,"([^\n]*)\n") do table.insert(lines,l) end
local out={}
for i,l in ipairs(lines) do if string.find(l,"local function firstDropoff") or string.find(l,"local function deliver") then for j=i,i+45 do table.insert(out,j..": "..(lines[j] or "")) end table.insert(out,"----") end end
return table.concat(out,"\n")

